let deadline = ContinuousClock.now.advanced(by: budget)   // monotonic, at ingress
let result = try await withThrowingTaskGroup(of: Response.self) { group in
    group.addTask { try await callDownstream(req) }          // inherits cancellation
    group.addTask {
        while ContinuousClock.now < deadline {
            try await Task.sleep(for: .milliseconds(50))
        }
        throw DeadlineExceeded()
    }
    defer { group.cancelAll() }                              // expire => cancel the hop
    return try await group.next()!
}
